package main

import "fmt"

func main() {
	var s, t string
	fmt.Scan(&s, &t)

	var shours, smins, thours, tmins int
	fmt.Sscanf(s, "%d:%d", &shours, &smins)
	fmt.Sscanf(t, "%d:%d", &thours, &tmins)

	answerhours := shours - thours
	if answerhours < 0 {
		answerhours += 24
	}

	answermins := smins - tmins
	if answermins < 0 {
		answermins += 60
		answerhours--
		if answerhours < 0 {
			answerhours = 23
		}
	}

	fmt.Printf("%02d:%02d\n", answerhours, answermins)
}

